function cutHint(pasted){return pasted.length<=100?'\u0418\u0433\u0440\u0430 \u043F\u0440\u0438\u043D\u044F\u043B\u0430 \u0442\u043E\u043B\u044C\u043A\u043E '+pasted.length+' \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432: \u043C\u0435\u043D\u044E \u0411\u0435\u0434\u0440\u043E\u043A\u043C\u0430\u0442\u0438\u043A\u0438 \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u043B\u043E\u0441\u044C, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043F\u043E\u043B\u0435 \u043E\u0431\u044B\u0447\u043D\u043E\u0435 \u0438 \u043A\u043E\u0440\u043E\u0442\u043A\u043E\u0435. \u041F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u0437\u0430\u043A\u0440\u043E\u0439 Minecraft \u0438 \u0437\u0430\u043F\u0443\u0441\u0442\u0438 \u0441\u043D\u043E\u0432\u0430. \u0415\u0441\u043B\u0438 \u043D\u0435 \u043F\u043E\u043C\u043E\u0433\u043B\u043E \u2014 \u0432\u044B\u0431\u0435\u0440\u0438 \u043D\u0430 \u0441\u0430\u0439\u0442\u0435 \xAB\u0420\u0430\u0437\u043C\u0435\u0440 \u043F\u043E\u0440\u0446\u0438\u0438: 100 \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432\xBB \u0438 \u0432\u0441\u0442\u0430\u0432\u043B\u044F\u0439 \u043F\u043E\u0440\u0446\u0438\u0438 \u043F\u043E \u043E\u0434\u043D\u043E\u0439.':'\u041A\u043E\u0434 \u0432\u0441\u0442\u0430\u0432\u043B\u0435\u043D \u043D\u0435 \u0446\u0435\u043B\u0438\u043A\u043E\u043C: \u0438\u0433\u0440\u0430 \u043F\u0435\u0440\u0435\u0434\u0430\u043B\u0430 '+pasted.length+' \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432. \u0421\u043A\u043E\u043F\u0438\u0440\u0443\u0439 \u0435\u0433\u043E \u043D\u0430 \u0441\u0430\u0439\u0442\u0435 \u0437\u0430\u043D\u043E\u0432\u043E.';}
// One paste may hold the codes of every schematic of a pack: a code with a slot (\u2026:<slot>!) goes to that slot of this
