 const count=Math.ceil(raw.length/16000),prefix='bm:data_'+slot+'_'+id+'_',oldPointer=e.getDynamicProperty('bm:data_'+slot),oldLocal=e.getDynamicProperty('bm:data_local_'+slot),oldLink=e.getDynamicProperty('bm:link_'+slot);let old;try{old=JSON.parse(oldPointer);}catch{}
 try{for(let i=0;i<count;i++)e.setDynamicProperty(prefix+i,raw.slice(i*16000,(i+1)*16000));e.setDynamicProperty('bm:data_local_'+slot,true);e.setDynamicProperty('bm:data_'+slot,JSON.stringify({id,count}));e.setDynamicProperty('bm:link_'+slot,undefined);}
 catch(err){for(const [key,value]of [['bm:data_'+slot,oldPointer],['bm:data_local_'+slot,oldLocal],['bm:link_'+slot,oldLink]])try{e.setDynamicProperty(key,value);}catch{}if(old?.id!==id)for(let i=0;i<count;i++)try{e.setDynamicProperty(prefix+i,undefined);}catch{}throw Error('\u041C\u0438\u0440 \u043D\u0435 \u043F\u0440\u0438\u043D\u044F\u043B \u0441\u0445\u0435\u043C\u0443. \u041F\u0440\u0438\u043D\u044F\u0442\u044B\u0435 \u043F\u043E\u0440\u0446\u0438\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u044B; \u043F\u043E\u0432\u0442\u043E\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u043F\u043E\u0440\u0446\u0438\u044E \u043F\u043E\u0441\u043B\u0435 \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u044F \u043C\u0435\u0441\u0442\u0430. '+String(err?.message??err));}
