// Only on request (counting settings, bm:keep, off by default: it loads the world and keeps farms near the projector running):
// while its hologram is shown and counting is not paused, a projector keeps its chunks ticking (bm_anchor, tick_world).
function projectorAnchors(){for(const name of ['overworld','nether','the_end'])for(const e of world.getDimension(name).getEntities({type:TYPE}))try{const want=Boolean(e.getDynamicProperty('bm:keep'))&&Boolean(e.getProperty('bm:enabled'))&&!paused.has(e.id);if(Boolean(e.getDynamicProperty('bm:anchored'))!==want){e.triggerEvent?.(want?'bm:anchor_on':'bm:anchor_off');e.setDynamicProperty('bm:anchored',want);}}catch{}}
system.runInterval(projectorAnchors,40);
