function inventory(title,body,buttons,classic){const f=new ActionFormData().title((classic?'':'BM_LIST')+(title.startsWith('BM_')?'\u0411\u0435\u0434\u0440\u043E\u043A\u043C\u0430\u0442\u0438\u043A\u0430':title)).body(body);for(const [text,img]of buttons)f.button(text,img?'textures/ui/bm_'+img:undefined);return f;}
