// Servers: the player who placed a projector owns it. Others see its progress and materials but change nothing;
// operators may do everything. Projectors placed before 1.2.9 have no owner and stay open to everyone.
// playerPermissionLevel 2 = Operator; commandPermissionLevel 2+ = Admin, Host, Owner; isOp() exists only in beta APIs.
function isOp(p){try{return p?.playerPermissionLevel===2||(p?.commandPermissionLevel??0)>=2||p?.isOp?.()===true;}catch{return false;}}
function ownerOf(e){return e.getDynamicProperty('bm:owner_id')??null;}
function mayEdit(p,e){const o=ownerOf(e);return !o||o===String(p.id)||isOp(p);}
// bm:used orders a player's projectors for the counting limit (COUNT_PER_PLAYER): the ones used last keep counting.
function touch(e,p){if(ownerOf(e)!==String(p.id))return;e.setDynamicProperty('bm:used',Date.now());e.setDynamicProperty('bm:owner_op',isOp(p));e.setDynamicProperty('bm:owner_name',String(p.name??''));}
function claim(e,p){if(!p?.id)return;e.setDynamicProperty('bm:owner_id',String(p.id));touch(e,p);}
